def read_question(file):
    """Reads a json file of size N and return the number as integer.
    It creates two lists: one of questions and one of answers separately
    If there is an error, it prints what caused it
    """
    answers = {}
    questions = []
    try:
        with open(file, 'r') as file:
            for d in json.load(file):
                questions.append(d['question'])
                answers[d['question']] = d['answer']
    except FileNotFoundError as e:
        print(e)

